  "kd.sol3.sectors": "Servicios profesionales, consultoría, comercio, inmobiliaria, seguros, educación, industria y cualquier otro sector productivo.",
  "kd.sol4.category": "Sitio Web y Presencia Básica en Internet",
  "kd.sol4.desc": "Creación y gestión de sitio web profesional con CMS headless sobre PostgreSQL, optimizado para SEO, responsive y con panel de administración intuitivo para actualizar contenidos sin conocimientos técnicos.",
  "kd.sol4.feat1": "Diseño responsive y optimizado para móviles",
  "kd.sol4.feat2": "Gestión de contenidos con editor visual intuitivo",
  "kd.sol4.feat3": "Optimización SEO: posicionamiento en buscadores",
  "kd.sol4.feat4": "Dominio propio y certificado SSL incluido",
  "kd.sol4.feat5": "Multi-idioma y accesibilidad (WCAG)",
  "kd.sol4.feat6": "Analítica web integrada",
  "kd.sol4.sectors": "Autónomos, comercios, restaurantes, profesionales liberales, artesanos, startups, industria y cualquier otro sector productivo.",
  "kd.sol5.category": "Comercio Electrónico",
  "kd.sol5.desc": "Plataforma de comercio electrónico gestionada con Rebase sobre PostgreSQL para vender productos y servicios online con catálogo, carrito de compra, pasarela de pago y gestión de pedidos.",
  "kd.sol5.feat1": "Catálogo de productos con variantes, precios e imágenes",
  "kd.sol5.feat2": "Carrito de compra y proceso de checkout seguro",
  "kd.sol5.feat3": "Integración con pasarelas de pago (Stripe, Redsys, PayPal)",
  "kd.sol5.feat4": "Gestión de pedidos, envíos y devoluciones",
